{"cards": [{"node_code": "N_ffb819ef9a13a9c4", "definition": "研究脑、脊髓及周围神经系统的正常解剖结构、病理改变及其在CT、MRI、超声等影像中的表现，用于神经系统疾病的诊断与鉴别。", "boundary": "本节点涵盖颅脑、脊髓及周围神经的影像诊断，包括脑血管病、肿瘤、感染、脱髓鞘及先天畸形等。与“胸部影像诊断”的区别在于解剖部位不同；与“医学影像基础”的区别在于本节点侧重特定系统的临床征象分析，而非通用成像原理。", "includes": ["颅脑与脊髓的CT、MRI、CTA/MRA等影像诊断", "脑血管病、脑肿瘤、脑炎等疾病的影像特征与鉴别", "周围神经病变的影像评估"], "excludes": ["神经介入治疗操作（归入介入影像学）", "神经电生理检查（归入神经病学或相关专科）"], "sibling_distinctions": [{"other_code": "N_9631667c4d75c844", "rule": "本节点聚焦颅脑、脊髓及周围神经；胸部影像诊断聚焦肺、纵隔、胸壁等结构。"}, {"other_code": "N_7d0a1ecc304e71a7", "rule": "本节点聚焦神经系统；腹部与盆腔影像诊断聚焦腹腔脏器及盆腔器官。"}], "cross_boundary_rule": "若内容涉及神经系统疾病的影像表现与诊断，归入本节点；若涉及神经影像引导下的介入治疗，归入介入影像学。"}, {"node_code": "N_9631667c4d75c844", "definition": "研究肺、气管、支气管、纵隔、胸壁及胸膜的正常解剖与病理影像表现，用于呼吸系统及胸部相关疾病的诊断与评估。", "boundary": "本节点涵盖胸部X线、CT、MRI等影像诊断，包括肺炎、肺癌、气胸、纵隔肿瘤及胸膜病变等。与“中枢神经系统影像诊断”的区别在于解剖部位不同；与“腹部与盆腔影像诊断”的区别在于膈肌以上的胸部结构归属本节点，膈肌以下归属腹部。", "includes": ["肺、纵隔、胸膜的CT、X线、MRI影像诊断", "肺部感染、肿瘤、血管病变的影像特征与鉴别", "胸部外伤及先天性畸形的影像评估"], "excludes": ["胸部介入治疗操作（归入介入影像学）", "心脏及大血管的专项影像诊断（若树中有心血管影像分支则归入，否则可关联本节点）"], "sibling_distinctions": [{"other_code": "N_ffb819ef9a13a9c4", "rule": "本节点聚焦胸部结构；中枢神经系统影像诊断聚焦颅脑、脊髓及周围神经。"}, {"other_code": "N_7d0a1ecc304e71a7", "rule": "本节点聚焦膈肌以上的胸部结构；腹部与盆腔影像诊断聚焦膈肌以下的腹腔及盆腔器官。"}], "cross_boundary_rule": "若内容涉及胸部器官的影像表现与诊断，归入本节点；若涉及胸部影像引导下的介入治疗，归入介入影像学。"}, {"node_code": "N_7d0a1ecc304e71a7", "definition": "研究腹腔脏器（肝、胆、胰、脾、肾、胃肠等）及盆腔器官（膀胱、子宫、前列腺等）的正常解剖与病理影像表现，用于相关疾病的诊断与鉴别。", "boundary": "本节点涵盖腹部与盆腔的CT、MRI、超声等影像诊断，包括肝胆胰脾肾疾病、胃肠道肿瘤、盆腔炎症及肿瘤等。与“胸部影像诊断”的区别在于膈肌以下的结构归属本节点；与“骨关节与软组织影像诊断”的区别在于本节点侧重脏器实质，而非骨骼与软组织。", "includes": ["肝、胆、胰、脾、肾、胃肠的CT、MRI、超声影像诊断", "盆腔器官（膀胱、子宫、前列腺）的影像评估", "腹部外伤、感染、肿瘤及先天畸形的影像特征与鉴别"], "excludes": ["腹部与盆腔介入治疗操作（归入介入影像学）", "腹部与盆腔骨骼及软组织的影像诊断（归入骨关节与软组织影像诊断）"], "sibling_distinctions": [{"other_code": "N_9631667c4d75c844", "rule": "本节点聚焦膈肌以下的腹腔及盆腔器官；胸部影像诊断聚焦膈肌以上的胸部结构。"}, {"other_code": "N_2b452eb62960515c", "rule": "本节点侧重腹腔脏器实质；骨关节与软组织影像诊断侧重骨骼、关节及软组织病变。"}], "cross_boundary_rule": "若内容涉及腹腔或盆腔脏器的影像表现与诊断，归入本节点；若涉及腹部与盆腔影像引导下的介入治疗，归入介入影像学。"}]}
